package com.clothingstore;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String slug; private String category; private BigDecimal price; @Column(name="image_url") private String imageUrl; private boolean active=true; public Long getId(){return id;} public String getName(){return name;} public String getSlug(){return slug;} public String getCategory(){return category;} public BigDecimal getPrice(){return price;} public String getImageUrl(){return imageUrl;} public void setName(String v){name=v;} public void setSlug(String v){slug=v;} public void setCategory(String v){category=v;} public void setPrice(BigDecimal v){price=v;} public void setImageUrl(String v){imageUrl=v;} public void setActive(boolean v){active=v;} }
